/* Automatic checks for the pre-con decks (js/precons.js, generated by tools/build-precons.py): every list parses with the normal importer
 * into exactly 100 cards with its commander(s), nothing is skipped, there are NO duplicate decks (same card list, or the same commander(s)),
 * nothing is older than 2016, and the dropdown groups are tidy (newest first, each deck in one group). Run: node tests/test_precons.cjs */
'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const ctx = { window: {}, console };
ctx.self = ctx.window; ctx.globalThis = ctx;
vm.createContext(ctx);
for (const f of ['deck.js', 'precons.js']) vm.runInContext(fs.readFileSync(path.join(__dirname, '../js', f), 'utf8'), ctx, { filename: f });
const Deck = ctx.window.Deck || ctx.Deck, P = ctx.window.CTPrecons;
assert.ok(Deck && Deck.parse, 'Deck loaded'); assert.ok(Array.isArray(P) && P.length >= 100, 'a full set of pre-con decks: ' + (P && P.length));

const front = n => n.split(' // ')[0].trim();
const ids = new Set(), listKeys = new Set(), commanderKeys = new Set(), groupsSeen = [];
for (const p of P) {
  assert.ok(/^[a-z0-9_]+$/.test(p.id) && !ids.has(p.id), 'unique id: ' + p.id); ids.add(p.id);
  assert.ok(p.name && p.commander === p.name && p.group && p.code && /^\d{4}-\d{2}-\d{2}$/.test(p.date), 'fields: ' + p.id);
  assert.ok(p.date >= '2016-01-01', p.name + ' is older than 2016: ' + p.date);
  const r = Deck.parse(p.text);
  assert.equal((r.warnings || []).length, 0, p.name + ': nothing skipped: ' + JSON.stringify(r.warnings));
  assert.equal(r.commanders.map(c => front(c.name)).join(' + '), p.name, p.name + ': commander(s) read from the Commander block');
  assert.ok(r.commanders.length >= 1 && r.commanders.length <= 2 && r.commanders.every(c => c.qty === 1));
  const total = r.main.reduce((n, e) => n + e.qty, 0) + r.commanders.length;
  assert.equal(total, 100, p.name + ' has ' + total + ' cards, not 100');
  for (const c of r.commanders) assert.ok(!r.main.some(e => e.name === c.name), p.name + ': commander also in the 99');
  for (const e of r.main) assert.ok(!/\S\/\S/.test(e.name), p.name + ': ' + e.name + ' (split cards must be written "A // B")');
  // No duplicates: the same card list (printings ignored) may appear only once, and so may the same commander(s).
  const lk = JSON.stringify([r.commanders.map(c => c.name).sort(), r.main.map(e => [e.name, e.qty]).sort()]);
  assert.ok(!listKeys.has(lk), 'DUPLICATE deck list: ' + p.name); listKeys.add(lk);
  const ck = r.commanders.map(c => c.name).sort().join('|');
  assert.ok(!commanderKeys.has(ck), 'two decks share the commander(s) ' + ck); commanderKeys.add(ck);
  assert.ok(!/Collector's Edition/i.test(p.id + p.name + p.group), 'no Collector\'s Edition copies');
  if (groupsSeen[groupsSeen.length - 1] !== p.group) { assert.ok(!groupsSeen.includes(p.group), 'a group must be in one block: ' + p.group); groupsSeen.push(p.group); }
}
// Groups run newest first.
const firstDate = g => P.find(p => p.group === g).date;
for (let i = 1; i < groupsSeen.length; i++) assert.ok(firstDate(groupsSeen[i - 1]).slice(0, 4) >= firstDate(groupsSeen[i]).slice(0, 4), 'groups are newest first: ' + groupsSeen[i - 1] + ' before ' + groupsSeen[i]);
// The decks Chris first supplied are all there, and "Final Fantasy: 2025" holds its four decks.
const ff = P.filter(p => p.group === 'Final Fantasy: 2025').map(p => p.name).sort();
assert.deepEqual(Array.from(ff), ['Cloud, Ex-SOLDIER', 'Terra, Herald of Hope', "Tidus, Yuna's Guardian", "Y'shtola, Night's Blessed"].sort());
for (const n of ['Inquisitor Greyfax', 'The Swarmlord', 'Abaddon the Despoiler', 'Szarekh, the Silent King', 'Éowyn, Shieldmaiden', 'Sauron, Lord of the Rings', 'Frodo, Adventurous Hobbit + Sam, Loyal Attendant', 'Galadriel, Elven-Queen']) assert.ok(P.some(p => p.name === n), 'missing ' + n);
// A group label has one colon at most and never repeats the year twice.
for (const g of groupsSeen) assert.ok((g.match(/:/g) || []).length <= 1 && !/(\d{4}).*\1/.test(g), 'tidy group label: ' + g);
console.log('PASS precons: ' + P.length + ' pre-con decks in ' + groupsSeen.length + ' groups, 2016 or newer, each 100 cards with its commander(s), no duplicate lists or commanders');
